 2	/**
 3	 * @package Application
 4	 * @subpackage Composer
 5	 */
 6	
 7	declare(strict_types=1);
 8	
 9	namespace Application\Composer\IconBuilder;
10	
11	use AppUtils\OperationResult;
12	
13	/**
14	 * Orchestrator that reads icon definitions from a JSON source file, renders
15	 * PHP and JS method blocks, and replaces the content between the
16	 * {@see self::MARKER_START} and {@see self::MARKER_END} marker comments in
17	 * the respective target files.
18	 *
19	 * Designed for build-time use and has no dependency on the full application
20	 * bootstrap, the `LocalFrameworkClone`, or the `t()` translation function.
21	 *
22	 * @package Application
23	 * @subpackage Composer
24	 * @see IconsReader
25	 * @see PHPRenderer
26	 * @see JSRenderer
27	 */
28	class IconBuilder
29	{
30	    public const int ERROR_PHP_ICON_FILE_NOT_FOUND = 82301;
31	    public const int ERROR_JS_ICON_FILE_NOT_FOUND = 82302;
32	    public const int ERROR_START_MARKER_NOT_FOUND = 82303;
33	    public const int ERROR_WRITE_FAILED = 82304;
34	
35	    private const string MARKER_START = '/* START METHODS */';
36	    private const string MARKER_END = '/* END METHODS */';
37	
38	    private string $iconsJsonPath;
39	    private string $phpFilePath;
40	    private string $jsFilePath;
41	    private ?IconsReader $iconsReader = null;
42	
43	    /**
44	     * @param string $iconsJsonPath Path to the icons.json source file.
45	     * @param string $phpFilePath   Path to the PHP target file.
46	     * @param string $jsFilePath    Path to the JS target file.
47	     */
48	    public function __construct(
49	        string $iconsJsonPath,
50	        string $phpFilePath,
51	        string $jsFilePath
52	    )
53	    {
54	        $this->iconsJsonPath = $iconsJsonPath;
55	        $this->phpFilePath = $phpFilePath;
56	        $this->jsFilePath = $jsFilePath;
57	    }
58	
59	    /**
60	     * Returns the icons reader, creating it on first access.
61	     *
62	     * @return IconsReader
63	     */
64	    public function getIcons() : IconsReader
65	    {
66	        if($this->iconsReader === null)
67	        {
68	            $this->iconsReader = new IconsReader($this->iconsJsonPath);
69	        }
70	
71	        return $this->iconsReader;
72	    }
73	
74	    /**
75	     * Rebuilds the icon methods in both target PHP and JS files.
76	     *
77	     * Reads icon definitions from the JSON source, renders method code for
78	     * each language, and replaces the content between the
79	     * `START METHODS` / `END METHODS` marker comments in each target file.
80	     *
81	     * Returns a failed {@see OperationResult} when any of the following occur:
82	     * - The PHP target file does not exist ({@see self::ERROR_PHP_ICON_FILE_NOT_FOUND}).
83	     * - The JS target file does not exist ({@see self::ERROR_JS_ICON_FILE_NOT_FOUND}).
84	     * - A required marker is absent in either target file ({@see self::ERROR_START_MARKER_NOT_FOUND}).
85	     * - Writing a target file fails (e.g. read-only file, full disk) ({@see self::ERROR_WRITE_FAILED}).
86	     *
87	     * @return OperationResult
88	     */
89	    public function build() : OperationResult
90	    {
91	        $result = new OperationResult($this);
92	
93	        if(!file_exists($this->phpFilePath))
94	        {
95	            return $result->makeError(
96	                sprintf('PHP icon file not found: [%s].', $this->phpFilePath),
97	                self::ERROR_PHP_ICON_FILE_NOT_FOUND
98	            );
99	        }

