230	    public function test_build_phpFileMissing_returnsError() : void
231	    {
232	        $jsPath = $this->createTempFile($this->jsFileWithMarkers());
233	        $builder = new IconBuilder(
234	            $this->iconsJsonPath,
235	            '/nonexistent/path/Icon.php',
