139	    /**
140	     * Reads the target file, replaces the content between
141	     * {@see self::MARKER_START} and {@see self::MARKER_END} with the
142	     * rendered code, and writes the result back to the file.
143	     *
144	     * Sets the supplied result to an error state and returns it when either
145	     * marker is absent from the file.
146	     *
147	     * @param string $filePath  Absolute path of the target file.
148	     * @param string $rendered  Rendered method code to insert between the markers.
149	     * @param OperationResult $result Shared result instance for error reporting.
150	     * @return OperationResult The same result instance (possibly set to error).
151	     */
152	    private function insertIconCode(string $filePath, string $rendered, OperationResult $result) : OperationResult
153	    {
154	        $content = (string)file_get_contents($filePath);
155	
156	        $startPos = strpos($content, self::MARKER_START);
157	
158	        if($startPos === false)
159	        {
160	            return $result->makeError(
161	                sprintf(
162	                    'Start marker [%s] not found in file [%s].',
163	                    self::MARKER_START,
164	                    $filePath
165	                ),
166	                self::ERROR_START_MARKER_NOT_FOUND
167	            );
168	        }
169	
170	        $endPos = strpos($content, self::MARKER_END);
171	
172	        if($endPos === false)
173	        {
174	            return $result->makeError(
175	                sprintf(
176	                    'End marker [%s] not found in file [%s].',
177	                    self::MARKER_END,
178	                    $filePath
179	                ),
180	                self::ERROR_START_MARKER_NOT_FOUND
181	            );
182	        }
183	
184	        $afterStart = $startPos + strlen(self::MARKER_START);
185	
186	        $newContent =
187	            substr($content, 0, $afterStart) .
188	            $rendered .
189	            substr($content, $endPos);
190	
191	        // @ suppresses the native PHP warning; the return value is the authoritative failure signal.
192	        $written = @file_put_contents($filePath, $newContent);
193	
194	        if($written === false)
195	        {
196	            return $result->makeError(
197	                sprintf('Failed to write to file [%s].', $filePath),
198	                self::ERROR_WRITE_FAILED
199	            );
200	        }
201	
202	        return $result;
203	    }
